mapper.select:
SELECT o.id, o.order_no, o.user_id, o.hospital_id, o.setmeal_id, o.doctor_id, o.order_date, o.order_status, o.create_time, o.cancel_time, h.name AS hospital_name, s.name AS setmeal_name, s.type AS setmeal_type, s.price AS setmeal_price, doc.real_name AS doctor_name, doc.department AS doctor_department FROM orders o LEFT JOIN hospital h ON h.id = o.hospital_id LEFT JOIN setmeal s ON s.id = o.setmeal_id LEFT JOIN doctor doc ON doc.id = o.doctor_id WHERE o.user_id = #{userId}
AND o.order_status = #{orderStatus}
ORDER BY o.create_time DESC

mapper.update:
UPDATE orders
SET order_status = #{orderStatus}

    , cancel_time = #{cancelTime}

WHERE id = #{id}
